REPRO = ("import hashlib, json, random\n\n"
         "def row_hash(row):\n"
         "    return hashlib.sha256(json.dumps(row, sort_keys=True, ensure_ascii=False).encode()).hexdigest()\n\n"
         "def dataset_fingerprint(rows):\n"
         "    \"\"\"жолдардың ретіне тәуелсіз, мультижиынға тәуелді саусақ ізі\"\"\"\n"
         "    return hashlib.sha256(''.join(sorted(row_hash(r) for r in rows)).encode()).hexdigest()[:16]\n\n"
         "data = [{'user': i, 'score': (i * 37) % 100, 'label': i % 3 == 0} for i in range(500)]\n"
         "shuffled = data[:]\n"
         "random.Random(7).shuffle(shuffled)\n"
         "edited = [dict(r) for r in data]\n"
         "edited[123]['score'] += 1\n\n"
         "print('бастапқы:     ', dataset_fingerprint(data))\n"
         "print('араластырылған:', dataset_fingerprint(shuffled), '(бірдей - рет маңызды емес)')\n"
         "print('бір өзгеріс:  ', dataset_fingerprint(edited), '(басқа)')\n\n"
         "def train(rows, seed):\n"
         "    rng = random.Random(seed)\n"
         "    sample = rng.sample(rows, 50)\n"
         "    return round(sum(r['score'] for r in sample) / 50, 2)\n"
         "run = {'data': dataset_fingerprint(data), 'seed': 42, 'code': 'git:3f2a9c1', 'params': {'lr': 0.01}}\n"
         "print('эксперимент:', run, '-> нәтиже', train(data, run['seed']), 'қайталау:', train(data, run['seed']))")

