VALID = ("SCHEMA = {\n"
         "    'age':    {'type': int,   'min': 5,   'max': 20,  'nullable': False},\n"
         "    'grade':  {'type': int,   'min': 1,   'max': 11,  'nullable': False},\n"
         "    'score':  {'type': float, 'min': 0.0, 'max': 100.0, 'nullable': True},\n"
         "    'region': {'type': str,   'allowed': {'Алматы', 'Астана', 'Шымкент', 'Қарағанды'}, 'nullable': False},\n"
         "}\n"
         "MAX_NULL_SHARE = {'score': 0.1}\n\n"
         "def check_row(row):\n"
         "    errs = []\n"
         "    for col, rule in SCHEMA.items():\n"
         "        v = row.get(col)\n"
         "        if v is None:\n"
         "            if not rule['nullable']:\n"
         "                errs.append(f'{col}: бос')\n"
         "            continue\n"
         "        if not isinstance(v, rule['type']) or isinstance(v, bool):\n"
         "            errs.append(f'{col}: типі {type(v).__name__}')\n"
         "        elif 'min' in rule and not rule['min'] <= v <= rule['max']:\n"
         "            errs.append(f'{col}: {v} шектен тыс')\n"
         "        elif 'allowed' in rule and v not in rule['allowed']:\n"
         "            errs.append(f'{col}: белгісіз мән {v!r}')\n"
         "    return errs\n\n"
         "def check_batch(rows):\n"
         "    bad = {i: e for i, r in enumerate(rows) if (e := check_row(r))}\n"
         "    for col, share in MAX_NULL_SHARE.items():\n"
         "        nulls = sum(r.get(col) is None for r in rows) / len(rows)\n"
         "        if nulls > share:\n"
         "            bad['batch'] = [f'{col}: бос үлесі {nulls:.0%} > {share:.0%}']\n"
         "    return bad\n\n"
         "batch = [\n"
         "    {'age': 15, 'grade': 9, 'score': 87.5, 'region': 'Алматы'},\n"
         "    {'age': 15, 'grade': 9, 'score': None, 'region': 'Астана'},\n"
         "    {'age': 150, 'grade': 9, 'score': 70.0, 'region': 'Алматы'},\n"
         "    {'age': 14, 'grade': '8', 'score': 65.0, 'region': 'алматы'},\n"
         "    {'age': 16, 'grade': 10, 'score': None, 'region': 'Шымкент'},\n"
         "]\n"
         "for k, v in check_batch(batch).items():\n"
         "    print(k, v)")

