LEAK = ("import random\n\n"
        "rng = random.Random(3)\n"
        "# Әр оқушының бірнеше жазбасы бар (әртүрлі айлар); бір оқушының жазбалары ұқсас\n"
        "students = {f's{i}': rng.random() < 0.4 for i in range(300)}          # шын белгі: емтиханнан өте ала ма\n"
        "rows = [(s, m, students[s]) for s in students for m in range(5)]\n\n"
        "def split_random(rows, p_test=0.2):\n"
        "    flags = [rng.random() < p_test for _ in rows]\n"
        "    return [r for r, f in zip(rows, flags) if not f], [r for r, f in zip(rows, flags) if f]\n\n"
        "def split_by_group(rows, p_test=0.2):\n"
        "    test_ids = {s for s in students if rng.random() < p_test}\n"
        "    return [r for r in rows if r[0] not in test_ids], [r for r in rows if r[0] in test_ids]\n\n"
        "def memorizer_accuracy(train, test):\n"
        "    \"\"\"оқытуда көрген оқушының белгісін «есте сақтайтын» модель; көрмегенге көпшілік класты береді\"\"\"\n"
        "    memory = {s: y for s, _, y in train}\n"
        "    majority = sum(y for *_, y in train) * 2 > len(train)\n"
        "    return sum(memory.get(s, majority) == y for s, _, y in test) / len(test)\n\n"
        "for name, f in [('кездейсоқ бөлу', split_random), ('оқушы бойынша бөлу', split_by_group)]:\n"
        "    train, test = f(rows)\n"
        "    train_ids = {r[0] for r in train}\n"
        "    seen = sum(s in train_ids for s, _, _ in test) / len(test)\n"
        "    print(f'{name:18}: тесттегі жазбалардың {seen:.0%}-ының оқушысы оқытуда бар, «есте сақтаушы» дәлдігі {memorizer_accuracy(train, test):.2f}')")

