METRICS = ("# (болжанған ықтималдық, шын белгі): 1 - оқушы емтиханнан өтпеу қаупі бар\n"
           "preds = [(0.95, 1), (0.85, 1), (0.80, 0), (0.70, 1), (0.60, 0), (0.55, 1), (0.40, 0), (0.30, 1), (0.20, 0), (0.10, 0)]\n\n"
           "def confusion(preds, t):\n"
           "    tp = sum(p >= t and y for p, y in preds)\n"
           "    fp = sum(p >= t and not y for p, y in preds)\n"
           "    fn = sum(p < t and y for p, y in preds)\n"
           "    tn = sum(p < t and not y for p, y in preds)\n"
           "    return tp, fp, fn, tn\n\n"
           "C_FP, C_FN = 1, 4      # жалған дабыл (қосымша сабақ) арзан, қаупі бар оқушыны жіберу қымбат\n"
           "for t in (0.25, 0.5, 0.75):\n"
           "    tp, fp, fn, tn = confusion(preds, t)\n"
           "    prec = tp / (tp + fp) if tp + fp else 0\n"
           "    rec = tp / (tp + fn)\n"
           "    f1 = 2 * prec * rec / (prec + rec) if prec + rec else 0\n"
           "    cost = C_FP * fp + C_FN * fn\n"
           "    print(f't = {t}: precision {prec:.2f}, recall {rec:.2f}, F1 {f1:.2f}, шығын {cost}')\n"
           "print('теориялық оңтайлы шек (калибрленген модельде): t* =', C_FP / (C_FP + C_FN))")

